{
  "name": "PDF Form Builder",
  "description": "A web application to upload PDFs, drag-and-drop data fields onto them, and generate a new PDF with filled data."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { pdfjs } from 'react-pdf';

// Configure the worker for react-pdf. 
// We use the CDN version matching the installed version to avoid build complexities.
pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum FieldType {
  TEXT = 'TEXT',
  DATE = 'DATE',
  NUMBER = 'NUMBER'
}

export interface PDFField {
  id: string;
  type: FieldType;
  name: string;
  value: string; // The sample data to print
  pageIndex: number; // Which page this field belongs to
  x: number; // X position in PDF Points (relative to unscaled PDF)
  y: number; // Y position in PDF Points
  width: number; // Width in PDF Points
  height: number; // Height in PDF Points
}

export interface AppState {
  file: File | null;
  numPages: number;
  fields: PDFField[];
  scale: number; // Zoom level (1 = 100%)
  selectedFieldId: string | null;
}

import React, { useState } from 'react';
import { PDFUploader } from './components/PDFUploader';
import { Workspace } from './components/Workspace';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
  };

  const handleReset = () => {
    setFile(null);
  };

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold">
            P
          </div>
          <h1 className="text-xl font-bold text-gray-800">PDF Form Builder</h1>
        </div>
        {file && (
           <button 
             onClick={handleReset}
             className="text-sm text-gray-500 hover:text-red-500 font-medium transition-colors"
           >
             Upload Different File
           </button>
        )}
      </header>

      <main className="flex-1 flex flex-col overflow-hidden">
        {!file ? (
          <PDFUploader onFileSelect={handleFileSelect} />
        ) : (
          <Workspace file={file} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useCallback } from 'react';
import { Upload, FileText } from 'lucide-react';

interface PDFUploaderProps {
  onFileSelect: (file: File) => void;
}

export const PDFUploader: React.FC<PDFUploaderProps> = ({ onFileSelect }) => {
  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      const files = e.dataTransfer.files;
      if (files.length > 0 && files[0].type === 'application/pdf') {
        onFileSelect(files[0]);
      } else {
        alert('Please upload a valid PDF file.');
      }
    },
    [onFileSelect]
  );

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      if (e.target.files[0].type === 'application/pdf') {
        onFileSelect(e.target.files[0]);
      } else {
         alert('Please upload a valid PDF file.');
      }
    }
  };

  return (
    <div className="flex-1 flex flex-col items-center justify-center p-8 bg-gray-50">
      <div className="max-w-xl w-full text-center">
        <h2 className="text-3xl font-bold text-gray-900 mb-4">Upload your Document</h2>
        <p className="text-gray-600 mb-8">
          Upload a PDF to start adding data fields. The original file will serve as the background template.
        </p>

        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          className="border-2 border-dashed border-gray-300 rounded-xl bg-white p-12 transition-all hover:border-blue-500 hover:shadow-lg cursor-pointer group"
        >
          <div className="flex flex-col items-center gap-4">
            <div className="p-4 bg-blue-50 rounded-full group-hover:bg-blue-100 transition-colors">
              <Upload className="w-10 h-10 text-blue-600" />
            </div>
            <div className="space-y-2">
              <p className="text-lg font-medium text-gray-900">
                Drag & drop your PDF here
              </p>
              <p className="text-sm text-gray-500">
                or <span className="text-blue-600 font-medium">browse files</span> on your computer
              </p>
            </div>
          </div>
          <input
            type="file"
            accept="application/pdf"
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            onChange={handleInputChange}
          />
        </div>

        <div className="mt-8 flex items-center justify-center gap-2 text-sm text-gray-400">
          <FileText className="w-4 h-4" />
          <span>Maximum file size: 10MB</span>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Rnd } from 'react-rnd';
import { PDFField, FieldType } from '../types';
import { GripVertical, X } from 'lucide-react';

interface DraggableFieldProps {
  field: PDFField;
  scale: number;
  isSelected: boolean;
  onUpdate: (id: string, updates: Partial<PDFField>) => void;
  onSelect: (id: string) => void;
  onDelete: (id: string) => void;
}

export const DraggableField: React.FC<DraggableFieldProps> = ({
  field,
  scale,
  isSelected,
  onUpdate,
  onSelect,
  onDelete,
}) => {
  // Determine color based on type
  const getColors = () => {
    switch (field.type) {
      case FieldType.DATE:
        return 'bg-green-100 border-green-500 text-green-800';
      case FieldType.NUMBER:
        return 'bg-purple-100 border-purple-500 text-purple-800';
      default:
        return 'bg-blue-100 border-blue-500 text-blue-800';
    }
  };

  return (
    <Rnd
      size={{ width: field.width * scale, height: field.height * scale }}
      position={{ x: field.x * scale, y: field.y * scale }}
      onDragStop={(e, d) => {
        onUpdate(field.id, { x: d.x / scale, y: d.y / scale });
      }}
      onResizeStop={(e, direction, ref, delta, position) => {
        onUpdate(field.id, {
          width: parseInt(ref.style.width) / scale,
          height: parseInt(ref.style.height) / scale,
          x: position.x / scale,
          y: position.y / scale,
        });
      }}
      bounds="parent"
      minWidth={50 * scale}
      minHeight={20 * scale}
      // Only allow drag from the handle to prevent accidental moves when selecting text
      dragHandleClassName="drag-handle"
      className={`absolute flex flex-col group ${isSelected ? 'z-50' : 'z-10'}`}
      onClick={(e) => {
        e.stopPropagation();
        onSelect(field.id);
      }}
    >
      <div
        className={`w-full h-full border-2 rounded shadow-sm flex flex-col overflow-hidden relative transition-colors ${
          isSelected ? 'border-blue-600 ring-2 ring-blue-300 ring-opacity-50' : 'border-dashed ' + getColors().split(' ')[1]
        } ${getColors()}`}
      >
        {/* Header / Drag Handle */}
        {isSelected && (
           <div className="absolute -top-3 -right-3 z-50">
             <button 
                onClick={(e) => {
                    e.stopPropagation();
                    onDelete(field.id);
                }}
                className="bg-red-500 text-white rounded-full p-1 hover:bg-red-600 shadow-sm"
             >
                <X size={12} />
             </button>
           </div>
        )}

        {/* Content Area */}
        <div className="flex-1 flex items-center px-1 overflow-hidden relative">
            <div className={`drag-handle absolute left-0 top-0 bottom-0 w-4 flex items-center justify-center cursor-move hover:bg-black/5 ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                <GripVertical size={12} />
            </div>
            <span className="text-xs font-semibold pl-4 truncate select-none pointer-events-none w-full">
                {field.name}
            </span>
        </div>

        {/* Preview Value */}
        <div className="px-1 pb-0.5 text-[10px] opacity-70 truncate select-none pl-4">
             {field.value || '(Empty)'}
        </div>
      </div>
    </Rnd>
  );
};

import { PDFDocument, rgb, StandardFonts } from 'pdf-lib';
import { PDFField } from '../types';

export const generateFinalPDF = async (
  originalFile: File,
  fields: PDFField[]
): Promise<Uint8Array> => {
  // 1. Read the original file
  const arrayBuffer = await originalFile.arrayBuffer();

  // 2. Load the PDFDocument
  const pdfDoc = await PDFDocument.load(arrayBuffer);

  // 3. Embed font (Standard Helvetica for this demo)
  const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);

  // 4. Iterate over fields and draw them
  const pages = pdfDoc.getPages();

  for (const field of fields) {
    // Validate page index
    if (field.pageIndex < 0 || field.pageIndex >= pages.length) continue;

    const page = pages[field.pageIndex];
    const { height } = page.getSize();

    // pdf-lib coordinate system: (0,0) is bottom-left
    // React/DOM coordinate system: (0,0) is top-left
    // We need to invert the Y axis.
    // field.y is stored from the top (as it comes from DOM logic)
    // We also need to account for the height of the field text block itself to align generally to top-left of the box

    // For simplicity in this demo, we assume the visual box is where the text starts.
    // A more robust solution would handle multiline wrapping and exact padding.
    const pdfY = height - field.y - (field.height / 2) - 4; // Simple centering adjustment

    page.drawText(field.value, {
      x: field.x + 5, // Slight padding
      y: pdfY,
      size: 12,
      font: helveticaFont,
      color: rgb(0, 0, 0),
      maxWidth: field.width - 10,
    });
  }

  // 5. Serialize
  const pdfBytes = await pdfDoc.save();
  return pdfBytes;
};

export const downloadBlob = (data: Uint8Array, filename: string) => {
  const blob = new Blob([data], { type: 'application/pdf' });
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  window.URL.revokeObjectURL(url);
};

import React, { useState, useRef, useEffect } from 'react';
import { Document, Page } from 'react-pdf';
import { PDFField, FieldType } from '../types';
import { DraggableField } from './DraggableField';
import { Toolbar } from './Toolbar';
import { generateFinalPDF, downloadBlob } from '../services/pdfService';
import { ZoomIn, ZoomOut, Maximize, MousePointer } from 'lucide-react';
import 'react-pdf/dist/esm/Page/AnnotationLayer.css';
import 'react-pdf/dist/esm/Page/TextLayer.css';

interface WorkspaceProps {
  file: File;
}

export const Workspace: React.FC<WorkspaceProps> = ({ file }) => {
  const [numPages, setNumPages] = useState<number>(0);
  const [scale, setScale] = useState<number>(1.0);
  const [fields, setFields] = useState<PDFField[]>([]);
  const [selectedFieldId, setSelectedFieldId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  // Ref to scroll container to handle dropping in correct view
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const onDocumentLoadSuccess = ({ numPages }: { numPages: number }) => {
    setNumPages(numPages);
  };

  const handleAddField = (type: FieldType) => {
    // Default to center of the current view or top of page 1
    const newField: PDFField = {
      id: crypto.randomUUID(),
      type,
      name: `New ${type} Field`,
      value: '',
      pageIndex: 0, // Default to first page for now
      x: 50,
      y: 50,
      width: 200,
      height: 40,
    };
    setFields((prev) => [...prev, newField]);
    setSelectedFieldId(newField.id);
  };

  const handleUpdateField = (id: string, updates: Partial<PDFField>) => {
    setFields((prev) =>
      prev.map((f) => (f.id === id ? { ...f, ...updates } : f))
    );
  };

  const handleDeleteField = (id: string) => {
    setFields((prev) => prev.filter((f) => f.id !== id));
    if (selectedFieldId === id) setSelectedFieldId(null);
  };

  const handleDownload = async () => {
    setIsGenerating(true);
    try {
      const pdfBytes = await generateFinalPDF(file, fields);
      downloadBlob(pdfBytes, 'filled_document.pdf');
    } catch (error) {
      console.error('Failed to generate PDF', error);
      alert('Error generating PDF. Please check console.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-full bg-gray-100 overflow-hidden relative">
      {/* Zoom Controls Overlay */}
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 bg-white rounded-full shadow-lg border border-gray-200 px-4 py-2 flex items-center gap-4 z-40">
        <button 
            onClick={() => setScale(s => Math.max(0.5, s - 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Zoom Out"
        >
            <ZoomOut className="w-4 h-4 text-gray-600" />
        </button>
        <span className="text-sm font-medium w-12 text-center">
            {Math.round(scale * 100)}%
        </span>
        <button 
            onClick={() => setScale(s => Math.min(2.5, s + 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Zoom In"
        >
            <ZoomIn className="w-4 h-4 text-gray-600" />
        </button>
        <div className="w-px h-4 bg-gray-300 mx-1" />
        <button 
            onClick={() => setScale(1)}
            className="text-xs font-medium text-gray-500 hover:text-blue-600"
        >
            Reset
        </button>
      </div>

      {/* Main Canvas Area */}
      <div 
        ref={scrollContainerRef}
        className="flex-1 overflow-auto p-8 flex justify-center relative"
        onClick={() => setSelectedFieldId(null)}
      >
        <div className="relative shadow-2xl">
          <Document
            file={file}
            onLoadSuccess={onDocumentLoadSuccess}
            className="flex flex-col gap-8"
          >
            {Array.from(new Array(numPages), (el, index) => (
              <div key={`page_${index + 1}`} className="relative bg-white">
                <Page
                  pageNumber={index + 1}
                  scale={scale}
                  renderTextLayer={false} 
                  renderAnnotationLayer={false}
                  className="shadow-sm"
                />

                {/* Overlay Layer for this specific page */}
                <div 
                    className="absolute inset-0 pointer-events-none"
                    style={{
                        // Ensure the overlay matches the page size exactly
                        // React-pdf usually renders canvas; we overlay a div
                        zIndex: 10
                    }}
                >
                    {/* Render fields belonging to this page */}
                    <div className="relative w-full h-full pointer-events-auto">
                        {fields
                          .filter((f) => f.pageIndex === index)
                          .map((field) => (
                            <DraggableField
                              key={field.id}
                              field={field}
                              scale={scale}
                              isSelected={selectedFieldId === field.id}
                              onUpdate={handleUpdateField}
                              onSelect={setSelectedFieldId}
                              onDelete={handleDeleteField}
                            />
                        ))}
                    </div>
                </div>
              </div>
            ))}
          </Document>
        </div>
      </div>

      {/* Right Sidebar Toolbar */}
      <Toolbar
        onAddField={handleAddField}
        selectedField={fields.find((f) => f.id === selectedFieldId) || null}
        onUpdateField={handleUpdateField}
        onDeleteField={handleDeleteField}
        onDownload={handleDownload}
        isGenerating={isGenerating}
      />
    </div>
  );
};

