export interface PDFField {
  id: string;
  type: FieldType;
  name: string; // Used for data mapping/ID
  value: string; // The visible content
  fontSize: number; // Font size in pts
  alignment: TextAlignment; // Horizontal alignment
  pageIndex: number; // Which page this field belongs to
  x: number; // X position in PDF Points
  y: number; // Y position in PDF Points
  width: number; // Width in PDF Points
  height: number; // Height in PDF Points
}

