export const generateFinalPDF = async (
  originalFile: File,
  fields: PDFField[]
): Promise<Uint8Array> => {
  // 1. Read the original file
  const arrayBuffer = await originalFile.arrayBuffer();

  // 2. Load the PDFDocument
  const pdfDoc = await PDFDocument.load(arrayBuffer);

  // 3. Embed font (Standard Helvetica for this demo)
  const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);

  // 4. Iterate over fields and draw them
  const pages = pdfDoc.getPages();

  for (const field of fields) {
    if (field.pageIndex < 0 || field.pageIndex >= pages.length) continue;

    const page = pages[field.pageIndex];
    const { height } = page.getSize();

    const fontSize = field.fontSize || 12;

    // Calculate Y position (Vertical Center approximation)
    // Inverting from DOM top-left to PDF bottom-left
    const pdfY = height - field.y - (field.height / 2) - (fontSize / 3); 

    // Calculate X position based on alignment
    let pdfX = field.x + 5; // Default 'left' with 5pt padding
    const textWidth = helveticaFont.widthOfTextAtSize(field.value, fontSize);

    if (field.alignment === 'center') {
      // Center: Field Start X + Half Width - Half Text Width
      pdfX = field.x + (field.width / 2) - (textWidth / 2);
    } else if (field.alignment === 'right') {
      // Right: Field End X - Text Width - Padding
      pdfX = field.x + field.width - textWidth - 5;
    }

    page.drawText(field.value, {
      x: pdfX,
      y: pdfY,
      size: fontSize,
      font: helveticaFont,
      color: rgb(0, 0, 0),
      maxWidth: field.width - 10, // Safety margin
    });
  }

  // 5. Serialize
  const pdfBytes = await pdfDoc.save();
  return pdfBytes;
};

