  onUpdateField: (id: string, updates: Partial<PDFField>) => void;
  onDeleteField: (id: string) => void;
  onDownload: () => void;
  onExportSchema: () => void;
  onImportData: (data: Record<string, string>) => void;
  isGenerating: boolean;
}

export const Toolbar: React.FC<ToolbarProps> = ({
  onAddField,
  selectedField,
  onUpdateField,
  onDeleteField,
  onDownload,
  onExportSchema,
  onImportData,
  isGenerating
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [copied, setCopied] = useState(false);

  const handleJsonUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        onImportData(json);
      } catch (error) {
        alert('File JSON không hợp lệ!');
        console.error(error);
      }
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // Helper to generate clean schema for display/copy
  const getFieldSchema = (field: PDFField) => {
    return {
        name: field.name,
        type: field.type,
        pageIndex: field.pageIndex,
        x: Number(field.x.toFixed(2)),
        y: Number(field.y.toFixed(2)),
        width: Number(field.width.toFixed(2)),
        height: Number(field.height.toFixed(2)),
        fontSize: field.fontSize,
        alignment: field.alignment
    };
  };

