    // Calculate scaling ratio to normalize original PDF size to A4
    // If original is Letter (612x792) and Target is A4 (595x841)
    // We stretch/shrink coordinates to match A4 percentage-wise.
    const ratioX = A4_WIDTH / currentWidth;
