import React, { useRef, useState } from 'react';
import { FieldType, PDFField } from '../types';
import { Type, Calendar, Hash, Download, Trash2, AlignLeft, AlignCenter, AlignRight, FileJson, UploadCloud, Copy, Check } from 'lucide-react';

interface ToolbarProps {
  onAddField: (type: FieldType) => void;
  selectedField: PDFField | null;
  onUpdateField: (id: string, updates: Partial<PDFField>) => void;
  onDeleteField: (id: string) => void;
  onDownload: () => void;
  onExportSchema: () => void;
  onImportData: (data: Record<string, string>) => void;
  onGetSchema: (field: PDFField) => any;
  isGenerating: boolean;
}

export const Toolbar: React.FC<ToolbarProps> = ({
  onAddField,
  selectedField,
  onUpdateField,
  onDeleteField,
  onDownload,
  onExportSchema,
  onImportData,
  onGetSchema,
  isGenerating
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [copied, setCopied] = useState(false);

  const handleJsonUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        onImportData(json);
      } catch (error) {
        alert('File JSON không hợp lệ!');
        console.error(error);
      }
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const handleCopySchema = (schema: any) => {
    navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Helper to extract schema for display
  const schema = selectedField ? onGetSchema(selectedField) : null;

  return (
    <div className="w-80 bg-white border-l border-gray-200 flex flex-col h-full shadow-lg z-20">
      {/* Add Fields Section */}
      <div className="p-5 border-b border-gray-200">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">
          Thêm trường
        </h3>
        <div className="grid grid-cols-2 gap-3">
          <button
            onClick={() => onAddField(FieldType.TEXT)}
            className="flex flex-col items-center justify-center p-3 rounded-lg border border-gray-200 hover:border-blue-500 hover:bg-blue-50 transition-all text-gray-700 hover:text-blue-700 gap-2"
          >
            <Type className="w-5 h-5" />
            <span className="text-xs font-medium">Văn bản</span>
          </button>
          <button
            onClick={() => onAddField(FieldType.DATE)}
            className="flex flex-col items-center justify-center p-3 rounded-lg border border-gray-200 hover:border-green-500 hover:bg-green-50 transition-all text-gray-700 hover:text-green-700 gap-2"
          >
            <Calendar className="w-5 h-5" />
            <span className="text-xs font-medium">Ngày</span>
          </button>
          <button
            onClick={() => onAddField(FieldType.NUMBER)}
            className="flex flex-col items-center justify-center p-3 rounded-lg border border-gray-200 hover:border-purple-500 hover:bg-purple-50 transition-all text-gray-700 hover:text-purple-700 gap-2"
          >
            <Hash className="w-5 h-5" />
            <span className="text-xs font-medium">Số</span>
          </button>
        </div>
      </div>

      {/* Data Management Section */}
      <div className="p-5 border-b border-gray-200 bg-gray-50/50">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">
          Dữ liệu & Cấu hình
        </h3>
        <div className="space-y-3">
            <button
                onClick={onExportSchema}
                className="w-full flex items-center justify-start gap-3 px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 text-sm font-medium text-gray-700 transition-colors"
            >
                <FileJson className="w-4 h-4 text-orange-500" />
                Xuất cấu hình (Schema)
            </button>

            <button
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex items-center justify-start gap-3 px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 text-sm font-medium text-gray-700 transition-colors"
            >
                <UploadCloud className="w-4 h-4 text-blue-500" />
                Nhập dữ liệu (JSON)
            </button>
            <input 
                type="file" 
                accept=".json" 
                ref={fileInputRef} 
                className="hidden" 
                onChange={handleJsonUpload}
            />
        </div>
      </div>

      {/* Field Properties Section */}
      <div className="flex-1 overflow-y-auto p-5">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">
          Thuộc tính
        </h3>
