import React, { useState, useRef } from 'react';
import { Document, Page } from 'react-pdf';
import { PDFField, FieldType } from '../types';
import { DraggableField } from './DraggableField';
import { Toolbar } from './Toolbar';
import { generateFinalPDF, downloadBlob } from '../services/pdfService';
import { ZoomIn, ZoomOut, ZoomIn as ResetZoom } from 'lucide-react';

// Standard A4 Dimensions in PDF Points (72 DPI)
// Precision is key here.
const A4_WIDTH = 595.28;
const A4_HEIGHT = 841.89;

interface WorkspaceProps {
  file: File;
}

export const Workspace: React.FC<WorkspaceProps> = ({ file }) => {
  const [numPages, setNumPages] = useState<number>(0);
  const [scale, setScale] = useState<number>(1.0);
  const [fields, setFields] = useState<PDFField[]>([]);
  const [selectedFieldId, setSelectedFieldId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  // Store actual page dimensions to calculate scaling ratio
  const [pageDimensions, setPageDimensions] = useState<Record<number, { width: number; height: number }>>({});

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const onDocumentLoadSuccess = ({ numPages }: { numPages: number }) => {
    setNumPages(numPages);
  };

  // Capture original page dimensions (in Points) when page loads
  const onPageLoadSuccess = (page: any, pageIndex: number) => {
    // page.originalWidth/Height are in PDF points (72dpi)
    setPageDimensions(prev => ({
        ...prev,
        [pageIndex]: {
            width: page.originalWidth,
            height: page.originalHeight
        }
    }));
  };

  const handleAddField = (type: FieldType) => {
    const nextIndex = fields.length + 1;
    const newField: PDFField = {
      id: crypto.randomUUID(),
      type,
      name: `field_${nextIndex}`, 
      value: '', 
      fontSize: 12,
      alignment: 'center', 
      pageIndex: 0, 
      x: 50,
      y: 50,
      width: 200,
      height: 40,
    };
    setFields((prev) => [...prev, newField]);
    setSelectedFieldId(newField.id);
  };

  const handleUpdateField = (id: string, updates: Partial<PDFField>) => {
    setFields((prev) =>
      prev.map((f) => (f.id === id ? { ...f, ...updates } : f))
    );
  };

  const handleDeleteField = (id: string) => {
    setFields((prev) => prev.filter((f) => f.id !== id));
    if (selectedFieldId === id) setSelectedFieldId(null);
  };

  // Helper to convert a single field to Standard A4 Text Coordinates
  // Calculates the actual insertion point (Anchor) of the text, not the box.
  const getStandardPDFSchema = (field: PDFField) => {
    const pageDim = pageDimensions[field.pageIndex];

    // Fallback if page not loaded yet
    const currentWidth = pageDim ? pageDim.width : A4_WIDTH;
    const currentHeight = pageDim ? pageDim.height : A4_HEIGHT;

    // Calculate scaling ratio to normalize original PDF size to A4
    const ratioX = A4_WIDTH / currentWidth;
    const ratioY = A4_HEIGHT / currentHeight;

    // 1. Scale Position & Dimensions (Box)
    const normX = field.x * ratioX;
    const normY = field.y * ratioY;
    const normWidth = field.width * ratioX;
    const normHeight = field.height * ratioY;
    const normFontSize = field.fontSize * ratioY;

    // 2. Calculate TEXT ANCHOR X based on alignment
    let textX = normX;
    if (field.alignment === 'center') {
        // Center: Middle of the box
        textX = normX + (normWidth / 2);
    } else if (field.alignment === 'right') {
        // Right: Right edge of the box minus padding (5pt)
        textX = normX + normWidth - 5;
    } else {
        // Left: Left edge of the box plus padding (5pt)
        textX = normX + 5;
    }

    // 3. Calculate TEXT BASELINE Y (Standard PDF Coords: 0 at Bottom)
    // The text is vertically centered in the box in the DOM.
    // DOM Center Y = normY + normHeight / 2
    // PDF Center Y = A4_HEIGHT - (normY + normHeight / 2)
    // Text Baseline is slightly below center. 
    // Heuristic: Center - fontSize / 3 (Matches visual rendering)
    const pdfBaselineY = A4_HEIGHT - normY - (normHeight / 2) - (normFontSize / 3);

    return {
        name: field.name,
        type: field.type,
        pageIndex: field.pageIndex,

        // Coordinates: TEXT ANCHOR point
        x: Number(textX.toFixed(2)),
        y: Number(pdfBaselineY.toFixed(2)), 

        // Font size scaled to match A4 resizing
        fontSize: Number(normFontSize.toFixed(2)),

        alignment: field.alignment,

        // Meta info
        _description: `X is ${field.alignment} anchor. Y is text baseline.`,
        _meta: {
            boxWidth: Number(normWidth.toFixed(2)),
            boxHeight: Number(normHeight.toFixed(2)),
            originalSize: [Number(currentWidth.toFixed(1)), Number(currentHeight.toFixed(1))],
            scaleFactor: [Number(ratioX.toFixed(3)), Number(ratioY.toFixed(3))]
        }
    };
  };

  // Export current field layout as JSON Schema with Correct Coordinates
  const handleExportSchema = () => {
    const schema = fields.map(f => getStandardPDFSchema(f));
    const jsonString = JSON.stringify(schema, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = 'pdf_text_coords_A4.json';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportData = (jsonData: Record<string, string>) => {
    setFields((prevFields) => {
      const updatedFields = prevFields.map((field) => {
        if (jsonData[field.name] !== undefined) {
          return { ...field, value: String(jsonData[field.name]) };
        }
        return field;
      });
      const filledCount = updatedFields.filter(f => jsonData[f.name] !== undefined).length;
      alert(`Đã tự động điền ${filledCount} trường dữ liệu thành công!`);
      return updatedFields;
    });
  };

  const handleDownload = async () => {
    setIsGenerating(true);
    try {
      const pdfBytes = await generateFinalPDF(file, fields);
      downloadBlob(pdfBytes, 'filled_document.pdf');
    } catch (error) {
      console.error('Failed to generate PDF', error);
      alert('Lỗi tạo PDF. Vui lòng kiểm tra console.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-full bg-gray-100 overflow-hidden relative">
      {/* Zoom Controls */}
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 bg-white rounded-full shadow-lg border border-gray-200 px-4 py-2 flex items-center gap-4 z-40">
        <button 
            onClick={() => setScale(s => Math.max(0.5, s - 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Thu nhỏ"
        >
            <ZoomOut className="w-4 h-4 text-gray-600" />
        </button>
        <span className="text-sm font-medium w-12 text-center">
            {Math.round(scale * 100)}%
        </span>
        <button 
            onClick={() => setScale(s => Math.min(2.5, s + 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Phóng to"
        >
            <ZoomIn className="w-4 h-4 text-gray-600" />
        </button>
      </div>

      {/* Main Canvas Area */}
      <div 
        ref={scrollContainerRef}
        className="flex-1 overflow-auto p-8 flex justify-center relative"
        onClick={() => setSelectedFieldId(null)}
      >
        <div className="relative shadow-2xl">
          <Document
            file={file}
            onLoadSuccess={onDocumentLoadSuccess}
            className="flex flex-col gap-8"
          >
            {Array.from(new Array(numPages), (el, index) => (
              <div key={`page_${index + 1}`} className="relative bg-white">
                <Page
                  pageNumber={index + 1}
                  scale={scale}
                  renderTextLayer={false} 
                  renderAnnotationLayer={false}
                  onLoadSuccess={(page) => onPageLoadSuccess(page, index)}
                  className="shadow-sm"
                />

                <div 
                    className="absolute inset-0 pointer-events-none"
                    style={{ zIndex: 10 }}
                >
                    <div className="relative w-full h-full pointer-events-auto">
                        {fields
                          .filter((f) => f.pageIndex === index)
                          .map((field) => (
                            <DraggableField
                              key={field.id}
                              field={field}
                              scale={scale}
                              isSelected={selectedFieldId === field.id}
                              onUpdate={handleUpdateField}
                              onSelect={setSelectedFieldId}
                              onDelete={handleDeleteField}
                            />
                        ))}
                    </div>
                </div>
              </div>
            ))}
          </Document>
        </div>
      </div>

      {/* Right Sidebar Toolbar */}
      <Toolbar
        onAddField={handleAddField}
        selectedField={fields.find((f) => f.id === selectedFieldId) || null}
        onUpdateField={handleUpdateField}
        onDeleteField={handleDeleteField}
        onDownload={handleDownload}
        onExportSchema={handleExportSchema}
        onImportData={handleImportData}
        onGetSchema={getStandardPDFSchema}
        isGenerating={isGenerating}
      />
    </div>
  );
};

import React, { useRef, useState } from 'react';
