          {isGenerating ? (
            <>
               <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
               Đang xử lý...
            </>
          ) : (
            <>
                <Download className="w-5 h-5" />
                Tạo PDF
            </>
          )}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Document, Page } from 'react-pdf';
import { PDFField, FieldType } from '../types';
import { DraggableField } from './DraggableField';
import { Toolbar } from './Toolbar';
import { generateFinalPDF, downloadBlob } from '../services/pdfService';
import { ZoomIn, ZoomOut, ZoomIn as ResetZoom } from 'lucide-react';

// Standard A4 Dimensions in PDF Points (72 DPI)
const A4_WIDTH = 595.28;
const A4_HEIGHT = 841.89;

interface WorkspaceProps {
  file: File;
}

export const Workspace: React.FC<WorkspaceProps> = ({ file }) => {
  const [numPages, setNumPages] = useState<number>(0);
  const [scale, setScale] = useState<number>(1.0);
  const [fields, setFields] = useState<PDFField[]>([]);
  const [selectedFieldId, setSelectedFieldId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [pageDimensions, setPageDimensions] = useState<Record<number, { width: number; height: number }>>({});

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const onDocumentLoadSuccess = ({ numPages }: { numPages: number }) => {
    setNumPages(numPages);
  };

  const onPageLoadSuccess = (page: any, pageIndex: number) => {
    setPageDimensions(prev => ({
        ...prev,
        [pageIndex]: {
            width: page.originalWidth,
            height: page.originalHeight
        }
    }));
  };

  const handleAddField = (type: FieldType) => {
    const nextIndex = fields.length + 1;
    const newField: PDFField = {
      id: crypto.randomUUID(),
      type,
      name: `field_${nextIndex}`, 
      value: '', 
      fontSize: 12,
      alignment: 'center', 
      pageIndex: 0, 
      x: 50,
      y: 50,
      width: 200,
      height: 40,
    };
    setFields((prev) => [...prev, newField]);
    setSelectedFieldId(newField.id);
  };

  const handleUpdateField = (id: string, updates: Partial<PDFField>) => {
    setFields((prev) =>
      prev.map((f) => (f.id === id ? { ...f, ...updates } : f))
    );
  };

  const handleDeleteField = (id: string) => {
    setFields((prev) => prev.filter((f) => f.id !== id));
    if (selectedFieldId === id) setSelectedFieldId(null);
  };

  // Helper to convert to Standard A4 and return MULTIPLE UNITS
  const getStandardPDFSchema = (field: PDFField) => {
    const pageDim = pageDimensions[field.pageIndex];
    const currentWidth = pageDim ? pageDim.width : A4_WIDTH;
    const currentHeight = pageDim ? pageDim.height : A4_HEIGHT;

    const ratioX = A4_WIDTH / currentWidth;
    const ratioY = A4_HEIGHT / currentHeight;

    // 1. Scale Position & Dimensions (Box)
    const normX = field.x * ratioX;
    const normY = field.y * ratioY;
    const normWidth = field.width * ratioX;
    const normHeight = field.height * ratioY;
    const normFontSize = field.fontSize * ratioY;

    // 2. Calculate CENTER X & Y (PDF Coordinates: Bottom-Left Origin)
    const centerX_pt = normX + (normWidth / 2);
    const centerY_pt = A4_HEIGHT - (normY + (normHeight / 2));

    // 3. Conversion Factors
    const PT_TO_MM = 0.352778;
    const PT_TO_INCH = 1 / 72;
    const PT_TO_PX_96DPI = 96 / 72; // 1.3333

    // Create multi-unit object
    return {
        name: field.name,
        type: field.type,
        pageIndex: field.pageIndex,

        // Base Unit (Points - Standard PDF)
        x: Number(centerX_pt.toFixed(2)),
        y: Number(centerY_pt.toFixed(2)), 

        fontSize: Number(normFontSize.toFixed(2)),
        alignment: field.alignment,

        // Detailed Unit Breakdowns for debugging
        _units: {
            pt: { 
                x: Number(centerX_pt.toFixed(2)), 
                y: Number(centerY_pt.toFixed(2)),
                label: "Points (72 DPI)"
            },
            mm: { 
                x: Number((centerX_pt * PT_TO_MM).toFixed(2)), 
                y: Number((centerY_pt * PT_TO_MM).toFixed(2)),
                label: "Millimeters" 
            },
            inch: { 
                x: Number((centerX_pt * PT_TO_INCH).toFixed(3)), 
                y: Number((centerY_pt * PT_TO_INCH).toFixed(3)),
                label: "Inches"
            },
            px96: { 
                x: Number((centerX_pt * PT_TO_PX_96DPI).toFixed(1)), 
                y: Number((centerY_pt * PT_TO_PX_96DPI).toFixed(1)),
                label: "Pixels (96 DPI Web)"
            }
        },

        _meta: {
            description: "Coordinates are CENTER X/Y relative to Bottom-Left",
            originalSize: [Number(currentWidth.toFixed(1)), Number(currentHeight.toFixed(1))]
        }
    };
  };

  const handleExportSchema = () => {
    const schema = fields.map(f => getStandardPDFSchema(f));
    const jsonString = JSON.stringify(schema, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = 'pdf_multi_unit_config.json';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportData = (jsonData: Record<string, string>) => {
    setFields((prevFields) => {
      const updatedFields = prevFields.map((field) => {
        if (jsonData[field.name] !== undefined) {
          return { ...field, value: String(jsonData[field.name]) };
        }
        return field;
      });
      const filledCount = updatedFields.filter(f => jsonData[f.name] !== undefined).length;
      alert(`Đã tự động điền ${filledCount} trường dữ liệu thành công!`);
      return updatedFields;
    });
  };

  const handleDownload = async () => {
    setIsGenerating(true);
    try {
      const pdfBytes = await generateFinalPDF(file, fields);
      downloadBlob(pdfBytes, 'filled_document.pdf');
    } catch (error) {
      console.error('Failed to generate PDF', error);
      alert('Lỗi tạo PDF. Vui lòng kiểm tra console.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-full bg-gray-100 overflow-hidden relative">
      {/* Zoom Controls */}
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 bg-white rounded-full shadow-lg border border-gray-200 px-4 py-2 flex items-center gap-4 z-40">
        <button 
            onClick={() => setScale(s => Math.max(0.5, s - 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Thu nhỏ"
        >
            <ZoomOut className="w-4 h-4 text-gray-600" />
        </button>
        <span className="text-sm font-medium w-12 text-center">
            {Math.round(scale * 100)}%
        </span>
        <button 
            onClick={() => setScale(s => Math.min(2.5, s + 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Phóng to"
        >
            <ZoomIn className="w-4 h-4 text-gray-600" />
        </button>
      </div>

      {/* Main Canvas Area */}
      <div 
        ref={scrollContainerRef}
        className="flex-1 overflow-auto p-8 flex justify-center relative"
        onClick={() => setSelectedFieldId(null)}
      >
        <div className="relative shadow-2xl">
          <Document
            file={file}
            onLoadSuccess={onDocumentLoadSuccess}
            className="flex flex-col gap-8"
          >
            {Array.from(new Array(numPages), (el, index) => (
              <div key={`page_${index + 1}`} className="relative bg-white">
                <Page
                  pageNumber={index + 1}
                  scale={scale}
                  renderTextLayer={false} 
                  renderAnnotationLayer={false}
                  onLoadSuccess={(page) => onPageLoadSuccess(page, index)}
                  className="shadow-sm"
                />

                <div 
                    className="absolute inset-0 pointer-events-none"
                    style={{ zIndex: 10 }}
                >
                    <div className="relative w-full h-full pointer-events-auto">
                        {fields
                          .filter((f) => f.pageIndex === index)
                          .map((field) => (
                            <DraggableField
                              key={field.id}
                              field={field}
                              scale={scale}
                              isSelected={selectedFieldId === field.id}
                              onUpdate={handleUpdateField}
                              onSelect={setSelectedFieldId}
                              onDelete={handleDeleteField}
                            />
                        ))}
                    </div>
                </div>
              </div>
            ))}
          </Document>
        </div>
      </div>

      {/* Right Sidebar Toolbar */}
      <Toolbar
        onAddField={handleAddField}
        selectedField={fields.find((f) => f.id === selectedFieldId) || null}
        onUpdateField={handleUpdateField}
        onDeleteField={handleDeleteField}
        onDownload={handleDownload}
        onExportSchema={handleExportSchema}
        onImportData={handleImportData}
        onGetSchema={getStandardPDFSchema}
        isGenerating={isGenerating}
      />
    </div>
  );
};

import React, { useRef, useState } from 'react';
import { FieldType, PDFField } from '../types';
import { Type, Calendar, Hash, Download, Trash2, AlignLeft, AlignCenter, AlignRight, FileJson, UploadCloud, Copy, Check, Ruler } from 'lucide-react';

interface ToolbarProps {
  onAddField: (type: FieldType) => void;
  selectedField: PDFField | null;
  onUpdateField: (id: string, updates: Partial<PDFField>) => void;
  onDeleteField: (id: string) => void;
  onDownload: () => void;
  onExportSchema: () => void;
  onImportData: (data: Record<string, string>) => void;
  onGetSchema: (field: PDFField) => any;
  isGenerating: boolean;
}

type UnitType = 'pt' | 'mm' | 'inch' | 'px96';

export const Toolbar: React.FC<ToolbarProps> = ({
  onAddField,
  selectedField,
  onUpdateField,
  onDeleteField,
  onDownload,
  onExportSchema,
  onImportData,
  onGetSchema,
  isGenerating
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [copied, setCopied] = useState(false);
  const [selectedUnit, setSelectedUnit] = useState<UnitType>('pt');

  const handleJsonUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        onImportData(json);
      } catch (error) {
        alert('File JSON không hợp lệ!');
        console.error(error);
      }
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const handleCopySchema = (schema: any) => {
    navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Helper to extract schema for display
  const schema = selectedField ? onGetSchema(selectedField) : null;

  const displayCoords = schema ? schema._units[selectedUnit] : { x: 0, y: 0 };

  return (
    <div className="w-80 bg-white border-l border-gray-200 flex flex-col h-full shadow-lg z-20">
      {/* Add Fields Section */}
      <div className="p-5 border-b border-gray-200">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">
          Thêm trường
        </h3>
        <div className="grid grid-cols-2 gap-3">
          <button
            onClick={() => onAddField(FieldType.TEXT)}
            className="flex flex-col items-center justify-center p-3 rounded-lg border border-gray-200 hover:border-blue-500 hover:bg-blue-50 transition-all text-gray-700 hover:text-blue-700 gap-2"
          >
            <Type className="w-5 h-5" />
            <span className="text-xs font-medium">Văn bản</span>
          </button>
          <button
            onClick={() => onAddField(FieldType.DATE)}
            className="flex flex-col items-center justify-center p-3 rounded-lg border border-gray-200 hover:border-green-500 hover:bg-green-50 transition-all text-gray-700 hover:text-green-700 gap-2"
          >
            <Calendar className="w-5 h-5" />
            <span className="text-xs font-medium">Ngày</span>
          </button>
          <button
            onClick={() => onAddField(FieldType.NUMBER)}
            className="flex flex-col items-center justify-center p-3 rounded-lg border border-gray-200 hover:border-purple-500 hover:bg-purple-50 transition-all text-gray-700 hover:text-purple-700 gap-2"
          >
            <Hash className="w-5 h-5" />
            <span className="text-xs font-medium">Số</span>
          </button>
        </div>
      </div>

      {/* Data Management Section */}
      <div className="p-5 border-b border-gray-200 bg-gray-50/50">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">
          Dữ liệu & Cấu hình
        </h3>
        <div className="space-y-3">
            <button
                onClick={onExportSchema}
                className="w-full flex items-center justify-start gap-3 px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 text-sm font-medium text-gray-700 transition-colors"
            >
                <FileJson className="w-4 h-4 text-orange-500" />
                Xuất cấu hình
            </button>

            <button
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex items-center justify-start gap-3 px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 text-sm font-medium text-gray-700 transition-colors"
            >
                <UploadCloud className="w-4 h-4 text-blue-500" />
                Nhập dữ liệu (JSON)
            </button>
            <input 
                type="file" 
                accept=".json" 
                ref={fileInputRef} 
                className="hidden" 
                onChange={handleJsonUpload}
            />
        </div>
      </div>

      {/* Field Properties Section */}
      <div className="flex-1 overflow-y-auto p-5">
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">
          Thuộc tính
        </h3>
        {selectedField && schema ? (
          <div className="space-y-4 animate-fadeIn">

            {/* Field Name (ID) */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Tên trường (ID)
              </label>
              <input
                type="text"
                value={selectedField.name}
                onChange={(e) =>
                  onUpdateField(selectedField.id, { name: e.target.value })
                }
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500 text-sm bg-gray-50 text-gray-900"
                placeholder="Ví dụ: ho_va_ten"
              />
            </div>

            {/* Field Content */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Nội dung hiển thị
              </label>
              <textarea
                value={selectedField.value}
                onChange={(e) =>
                  onUpdateField(selectedField.id, { value: e.target.value })
                }
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
              />
            </div>

            {/* Alignment */}
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
