              </label>
              <div className="flex bg-gray-100 rounded-md p-1 gap-1">
                <button
                    onClick={() => onUpdateField(selectedField.id, { alignment: 'left' })}
                    className={`flex-1 flex items-center justify-center p-1.5 rounded transition-colors ${selectedField.alignment === 'left' ? 'bg-white shadow-sm text-blue-600' : 'hover:bg-gray-200 text-gray-600'}`}
                    title="Trái"
                >
                    <AlignLeft className="w-4 h-4" />
                </button>
                <button
                    onClick={() => onUpdateField(selectedField.id, { alignment: 'center' })}
                    className={`flex-1 flex items-center justify-center p-1.5 rounded transition-colors ${selectedField.alignment === 'center' ? 'bg-white shadow-sm text-blue-600' : 'hover:bg-gray-200 text-gray-600'}`}
                     title="Giữa"
                >
                    <AlignCenter className="w-4 h-4" />
                </button>
                <button
                    onClick={() => onUpdateField(selectedField.id, { alignment: 'right' })}
                    className={`flex-1 flex items-center justify-center p-1.5 rounded transition-colors ${selectedField.alignment === 'right' ? 'bg-white shadow-sm text-blue-600' : 'hover:bg-gray-200 text-gray-600'}`}
                     title="Phải"
                >
                    <AlignRight className="w-4 h-4" />
                </button>
              </div>
            </div>

             {/* COORDINATES DISPLAY WITH UNIT SELECTOR */}
             <div className="bg-indigo-50 border border-indigo-200 rounded-md p-3 space-y-2">
                <div className="flex items-center justify-between mb-2">
                     <span className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                         <Ruler className="w-3 h-3" />
                         Tọa độ
                     </span>
                     <select 
                        value={selectedUnit}
                        onChange={(e) => setSelectedUnit(e.target.value as UnitType)}
                        className="text-[10px] border border-indigo-300 rounded px-1 py-0.5 text-indigo-800 bg-white focus:outline-none"
                     >
                         <option value="pt">Points (pt)</option>
                         <option value="mm">Millimeters (mm)</option>
                         <option value="inch">Inches (in)</option>
                         <option value="px96">Pixels (96 DPI)</option>
                     </select>
                </div>

                <div className="grid grid-cols-2 gap-2">
                    <div className="bg-white p-2 rounded border border-indigo-100">
                        <label className="text-[10px] text-gray-500 block uppercase font-semibold">Center X</label>
                        <div className="font-mono font-bold text-indigo-700 text-lg leading-tight mt-1">
                            {displayCoords.x}
                            <span className="text-[10px] font-normal text-gray-400 ml-1">{selectedUnit.replace('96','')}</span>
                        </div>
                    </div>
                    <div className="bg-white p-2 rounded border border-indigo-100">
                        <label className="text-[10px] text-gray-500 block uppercase font-semibold">Center Y</label>
                        <div className="font-mono font-bold text-indigo-700 text-lg leading-tight mt-1">
                            {displayCoords.y}
                            <span className="text-[10px] font-normal text-gray-400 ml-1">{selectedUnit.replace('96','')}</span>
                        </div>
                    </div>
                </div>
                <div className="text-[10px] text-indigo-600 italic text-center">
                    Gốc tọa độ: Góc dưới-trái (Bottom-Left)
                </div>
             </div>

             {/* Font Size */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Cỡ chữ (pt)
              </label>
              <div className="flex items-center gap-2">
                <input
                  type="range"
                  min="8"
                  max="72"
                  value={selectedField.fontSize}
                  onChange={(e) => onUpdateField(selectedField.id, { fontSize: parseInt(e.target.value) })}
                  className="flex-1"
                />
                <input
                  type="number"
                  value={selectedField.fontSize}
                  onChange={(e) => onUpdateField(selectedField.id, { fontSize: parseInt(e.target.value) })}
                  className="w-16 px-2 py-1 border border-gray-300 rounded text-center text-sm text-gray-900"
                />
              </div>
            </div>

            {/* JSON Schema Display */}
            <div className="mt-4 border-t border-gray-200 pt-4">
                <div className="flex items-center justify-between mb-2">
                    <label className="block text-sm font-bold text-gray-700">
                        JSON Schema Preview
                    </label>
                    <button
                        onClick={() => handleCopySchema(schema)}
                        className={`text-xs flex items-center gap-1 font-medium px-2 py-1 rounded transition-colors ${copied ? 'text-green-600 bg-green-50' : 'text-blue-600 hover:bg-blue-50'}`}
                    >
                        {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                        {copied ? 'Đã chép' : 'Sao chép'}
