            </div>

            <div className="pt-4 border-t border-gray-200 mt-4">
                <button
                    onClick={() => onDeleteField(selectedField.id)}
                    className="w-full flex items-center justify-center gap-2 px-4 py-2 border border-red-300 text-red-700 rounded-md hover:bg-red-50 text-sm font-medium transition-colors"
