import { PDFDocument, rgb, StandardFonts } from 'pdf-lib';
import { PDFField } from '../types';

export const generateFinalPDF = async (
  originalFile: File,
  fields: PDFField[]
): Promise<Uint8Array> => {
  // 1. Read the original file
  const arrayBuffer = await originalFile.arrayBuffer();

  // 2. Load the PDFDocument
  const pdfDoc = await PDFDocument.load(arrayBuffer);

  // 3. Embed font (Standard Helvetica for this demo)
  const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);

  // 4. Iterate over fields and draw them
  const pages = pdfDoc.getPages();

  for (const field of fields) {
    if (field.pageIndex < 0 || field.pageIndex >= pages.length) continue;

    const page = pages[field.pageIndex];
    const { height } = page.getSize();

    const fontSize = field.fontSize || 12;

    // --- COORDINATE SYSTEM TRANSFORMATION ---
    // Web (Input): Origin Top-Left. field.y is distance from top.
    // PDF (Output): Origin Bottom-Left. Y increases upwards.
    // "App Kia" Standard: The Y coordinate represents the position measured from the BOTTOM edge.
    // Since our visual editor has a box, we map the BOTTOM of the Visual Box to the Baseline Y in PDF.

    // Web Bottom Y = field.y (top) + field.height
    // PDF Y (from bottom) = Page Height - Web Bottom Y
    const pdfY = height - (field.y + field.height);

    // Calculate X position based on alignment to match the visual anchor
    let pdfX = field.x; // Default 'left' 

    const textWidth = helveticaFont.widthOfTextAtSize(field.value, fontSize);

    if (field.alignment === 'center') {
      // If we visually centered the box, the Anchor X in PDF terms is the center of that box.
      // pdf-lib drawText starts at X. To center text around X, we subtract half text width.
      // Target Center X = field.x + (field.width / 2)
      // Draw X = Target Center X - (Text Width / 2)
      pdfX = field.x + (field.width / 2) - (textWidth / 2);
    } else if (field.alignment === 'right') {
      // Target Right Edge = field.x + field.width
      // Draw X = Target Right Edge - Text Width
      pdfX = field.x + field.width - textWidth;
    } else {
        // Left alignment
        // Just add a tiny padding if the visual box has padding, otherwise strict Left
        pdfX = field.x + 2; 
    }

    page.drawText(field.value, {
      x: pdfX,
      y: pdfY, // Drawing at the bottom line of the box
      size: fontSize,
      font: helveticaFont,
      color: rgb(0, 0, 0),
      // We don't strictly enforce maxWidth in drawText to avoid clipping if user intended overflow, 
      // but strictly speaking it should be: maxWidth: field.width
    });
  }

  // 5. Serialize
  const pdfBytes = await pdfDoc.save();
  return pdfBytes;
};

export const downloadBlob = (data: Uint8Array, filename: string) => {
  const blob = new Blob([data], { type: 'application/pdf' });
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  window.URL.revokeObjectURL(url);
};

import React from 'react';
import { Rnd } from 'react-rnd';
import { PDFField, FieldType } from '../types';
import { GripVertical, X } from 'lucide-react';

interface DraggableFieldProps {
  field: PDFField;
  scale: number;
  isSelected: boolean;
  onUpdate: (id: string, updates: Partial<PDFField>) => void;
  onSelect: (id: string) => void;
  onDelete: (id: string) => void;
}

export const DraggableField: React.FC<DraggableFieldProps> = ({
  field,
  scale,
  isSelected,
  onUpdate,
  onSelect,
  onDelete,
}) => {
  // Determine color based on selection state
  const getColors = () => {
    if (isSelected) return 'bg-white/90 border-blue-600 shadow-md ring-1 ring-blue-200';
    return 'bg-white/50 border-blue-300 hover:border-blue-400 border-dashed';
  };

  const getJustify = () => {
    switch (field.alignment) {
      case 'center': return 'justify-center';
      case 'right': return 'justify-end';
      case 'left': 
      default: return 'justify-start';
    }
  };

  // Calculate Anchor Dot Position
  const getAnchorPosition = () => {
      // Always at bottom (y = 100%)
      const bottom = "-bottom-1"; 
      let left = "left-0"; // Default Left

      if (field.alignment === 'center') left = "left-1/2 -translate-x-1/2";
      if (field.alignment === 'right') left = "right-0";

      return `${bottom} ${left}`;
  };

  return (
    <Rnd
      size={{ width: field.width * scale, height: field.height * scale }}
      position={{ x: field.x * scale, y: field.y * scale }}
      onDragStop={(e, d) => {
        onUpdate(field.id, { x: d.x / scale, y: d.y / scale });
      }}
      onResizeStop={(e, direction, ref, delta, position) => {
        onUpdate(field.id, {
          width: parseInt(ref.style.width) / scale,
          height: parseInt(ref.style.height) / scale,
          x: position.x / scale,
          y: position.y / scale,
        });
      }}
      bounds="parent"
      minWidth={10 * scale}
      minHeight={10 * scale}
      dragHandleClassName="drag-handle"
      className={`absolute flex flex-col group ${isSelected ? 'z-50' : 'z-10'}`}
      onClick={(e) => {
        e.stopPropagation();
        onSelect(field.id);
      }}
    >
      <div
        className={`w-full h-full border rounded-sm transition-all flex items-end relative ${getColors()}`}
      >
        {/* Delete Button */}
        {isSelected && (
           <div className="absolute -top-3 -right-3 z-50">
             <button 
                onClick={(e) => {
                    e.stopPropagation();
                    onDelete(field.id);
                }}
                className="bg-red-500 text-white rounded-full p-1 hover:bg-red-600 shadow-sm"
             >
                <X size={12} />
             </button>
           </div>
        )}

        {/* Drag Handle */}
        <div className={`drag-handle absolute -left-3 top-0 bottom-0 w-3 flex items-center justify-center cursor-move ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
            <GripVertical size={14} className="text-gray-400" />
        </div>

        {/* VISUAL ANCHOR POINT (THE RED DOT) */}
        {isSelected && (
            <div className={`absolute w-2 h-2 bg-red-600 rounded-full z-50 shadow-sm border border-white ${getAnchorPosition()}`} title="Điểm đặt bút (Anchor Point)" />
        )}

        {/* Content Area - Aligned to Bottom (items-end) to match Baseline */}
        <div 
          className={`w-full h-full overflow-hidden px-0.5 pb-0.5 flex items-end ${getJustify()}`}
          style={{
            fontSize: `${field.fontSize * scale}px`,
            lineHeight: 1,
            color: '#000000',
            fontFamily: 'Helvetica, sans-serif',
            whiteSpace: 'nowrap'
          }}
        >
             {field.value || <span className="text-gray-400 italic text-[10px] opacity-50 pb-1">...</span>}
        </div>
      </div>
    </Rnd>
  );
};

import React, { useState, useRef } from 'react';
import { Document, Page } from 'react-pdf';
import { PDFField, FieldType } from '../types';
import { DraggableField } from './DraggableField';
import { Toolbar } from './Toolbar';
import { generateFinalPDF, downloadBlob } from '../services/pdfService';
import { ZoomIn, ZoomOut } from 'lucide-react';

interface WorkspaceProps {
  file: File;
}

export const Workspace: React.FC<WorkspaceProps> = ({ file }) => {
  const [numPages, setNumPages] = useState<number>(0);
  const [scale, setScale] = useState<number>(1.0);
  const [fields, setFields] = useState<PDFField[]>([]);
  const [selectedFieldId, setSelectedFieldId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [pageDimensions, setPageDimensions] = useState<Record<number, { width: number; height: number }>>({});

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const onDocumentLoadSuccess = ({ numPages }: { numPages: number }) => {
    setNumPages(numPages);
  };

  const onPageLoadSuccess = (page: any, pageIndex: number) => {
    setPageDimensions(prev => ({
        ...prev,
        [pageIndex]: {
            width: page.originalWidth, // Rendered width at scale 1 (should match PDF points)
            height: page.originalHeight
        }
    }));
  };

  const handleAddField = (type: FieldType) => {
    const nextIndex = fields.length + 1;
    // Default size appropriate for typical text
    const newField: PDFField = {
      id: crypto.randomUUID(),
      type,
      name: `field_${nextIndex}`, 
      value: '', 
      fontSize: 12,
      alignment: 'left', 
      pageIndex: 0, 
      x: 50,
      y: 100,
      width: 150,
      height: 20, // Height roughly matches line height
    };
    setFields((prev) => [...prev, newField]);
    setSelectedFieldId(newField.id);
  };

  const handleUpdateField = (id: string, updates: Partial<PDFField>) => {
    setFields((prev) =>
      prev.map((f) => (f.id === id ? { ...f, ...updates } : f))
    );
  };

  const handleDeleteField = (id: string) => {
    setFields((prev) => prev.filter((f) => f.id !== id));
    if (selectedFieldId === id) setSelectedFieldId(null);
  };

  // --- CORE LOGIC: Strict Cartesian Coordinate Calculation ---
  // Returns coordinates of the RED DOT (Anchor Point) relative to Bottom-Left
  const getAnchorCoordinates = (field: PDFField) => {
    const pageDim = pageDimensions[field.pageIndex];
    // Fallback to A4 if not loaded yet, but usually it is loaded.
    const pageWidth = pageDim ? pageDim.width : 595.28;
    const pageHeight = pageDim ? pageDim.height : 841.89;

    // 1. Calculate Y (Baseline/Bottom)
    // In Web: y is Top.
    // Box Bottom (Web) = field.y + field.height
    // PDF Y (from Bottom) = PageHeight - Box Bottom
    const pdfY = pageHeight - (field.y + field.height);

    // 2. Calculate X (Anchor)
    let pdfX = field.x; // Default Left

    if (field.alignment === 'center') {
        pdfX = field.x + (field.width / 2);
    } else if (field.alignment === 'right') {
        pdfX = field.x + field.width;
    }

    return {
        x: pdfX,
        y: pdfY,
        pageWidth,
        pageHeight
    };
  };

  const getStandardPDFSchema = (field: PDFField) => {
    const coords = getAnchorCoordinates(field);

    // Constants
    const PT_TO_MM = 1 / 2.835; 

    return {
        name: field.name,
        type: field.type,
        pageIndex: field.pageIndex,

        // Strict Cartesian Coordinates (Anchor Point)
        x: Number(coords.x.toFixed(2)),
        y: Number(coords.y.toFixed(2)), 

        fontSize: Number(field.fontSize.toFixed(2)),
        alignment: field.alignment,

        // Display Units
        _units: {
            pt: { 
                x: Number(coords.x.toFixed(2)), 
                y: Number(coords.y.toFixed(2)),
            },
            mm: { 
                x: Number((coords.x * PT_TO_MM).toFixed(2)), 
                y: Number((coords.y * PT_TO_MM).toFixed(2)),
            }
        },

        _meta: {
            description: "Coordinates refer to the ANCHOR POINT (Red Dot). Origin: Bottom-Left.",
            pageSize: { w: coords.pageWidth, h: coords.pageHeight }
        }
    };
  };

  const handleExportSchema = () => {
    const schema = fields.map(f => getStandardPDFSchema(f));
    const jsonString = JSON.stringify(schema, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = 'pdf_anchor_config.json';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportData = (jsonData: Record<string, string>) => {
    setFields((prevFields) => {
      const updatedFields = prevFields.map((field) => {
        if (jsonData[field.name] !== undefined) {
          return { ...field, value: String(jsonData[field.name]) };
        }
        return field;
      });
      const filledCount = updatedFields.filter(f => jsonData[f.name] !== undefined).length;
      alert(`Đã tự động điền ${filledCount} trường dữ liệu thành công!`);
      return updatedFields;
    });
  };

  const handleDownload = async () => {
    setIsGenerating(true);
    try {
      // Use dimensions from the actual loaded page if available
      const pdfBytes = await generateFinalPDF(file, fields);
      downloadBlob(pdfBytes, 'filled_document.pdf');
    } catch (error) {
      console.error('Failed to generate PDF', error);
      alert('Lỗi tạo PDF. Vui lòng kiểm tra console.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-full bg-gray-100 overflow-hidden relative">
      {/* Zoom Controls */}
      <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 bg-white rounded-full shadow-lg border border-gray-200 px-4 py-2 flex items-center gap-4 z-40">
        <button 
            onClick={() => setScale(s => Math.max(0.5, s - 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Thu nhỏ"
        >
            <ZoomOut className="w-4 h-4 text-gray-600" />
        </button>
        <span className="text-sm font-medium w-12 text-center">
            {Math.round(scale * 100)}%
        </span>
        <button 
            onClick={() => setScale(s => Math.min(2.5, s + 0.1))}
            className="p-1 hover:bg-gray-100 rounded-full"
            title="Phóng to"
        >
            <ZoomIn className="w-4 h-4 text-gray-600" />
        </button>
      </div>

      {/* Main Canvas Area */}
      <div 
        ref={scrollContainerRef}
        className="flex-1 overflow-auto p-8 flex justify-center relative"
        onClick={() => setSelectedFieldId(null)}
      >
        <div className="relative shadow-2xl">
          <Document
            file={file}
            onLoadSuccess={onDocumentLoadSuccess}
            className="flex flex-col gap-8"
          >
            {Array.from(new Array(numPages), (el, index) => (
              <div key={`page_${index + 1}`} className="relative bg-white">
                <Page
                  pageNumber={index + 1}
                  scale={scale}
                  renderTextLayer={false} 
                  renderAnnotationLayer={false}
                  onLoadSuccess={(page) => onPageLoadSuccess(page, index)}
                  className="shadow-sm"
                />

                <div 
                    className="absolute inset-0 pointer-events-none"
                    style={{ zIndex: 10 }}
                >
                    <div className="relative w-full h-full pointer-events-auto">
                        {fields
                          .filter((f) => f.pageIndex === index)
                          .map((field) => (
                            <DraggableField
                              key={field.id}
                              field={field}
                              scale={scale}
                              isSelected={selectedFieldId === field.id}
                              onUpdate={handleUpdateField}
                              onSelect={setSelectedFieldId}
                              onDelete={handleDeleteField}
                            />
                        ))}
                    </div>
                </div>
              </div>
            ))}
          </Document>
        </div>
      </div>

      {/* Right Sidebar Toolbar */}
      <Toolbar
        onAddField={handleAddField}
        selectedField={fields.find((f) => f.id === selectedFieldId) || null}
        onUpdateField={handleUpdateField}
        onDeleteField={handleDeleteField}
        onDownload={handleDownload}
        onExportSchema={handleExportSchema}
        onImportData={handleImportData}
        onGetSchema={getStandardPDFSchema}
        isGenerating={isGenerating}
      />
    </div>
  );
};

import { PDFDocument, rgb, StandardFonts } from 'pdf-lib';
import { PDFField } from '../types';

export const generateFinalPDF = async (
  originalFile: File,
  fields: PDFField[]
): Promise<Uint8Array> => {
  // 1. Read the original file
  const arrayBuffer = await originalFile.arrayBuffer();

  // 2. Load the PDFDocument
  const pdfDoc = await PDFDocument.load(arrayBuffer);

  // 3. Embed font (Standard Helvetica for this demo)
  const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);

  // 4. Iterate over fields and draw them
  const pages = pdfDoc.getPages();

  for (const field of fields) {
    if (field.pageIndex < 0 || field.pageIndex >= pages.length) continue;

    const page = pages[field.pageIndex];
    const { height } = page.getSize();

    const fontSize = field.fontSize || 12;

    // --- COORDINATE SYSTEM ---
    // User Visual: Box on screen. Text aligned to bottom of box (items-end).
    // Logic: The "Y" coordinate we want to draw at is the Bottom Edge of the Visual Box.

    // PDF Y (from bottom) = Page Height - (Box Top + Box Height)
    const pdfY = height - (field.y + field.height);

    const textWidth = helveticaFont.widthOfTextAtSize(field.value, fontSize);

    // Calculate DRAW X based on Alignment Anchor Logic
    let drawX = field.x; 

    if (field.alignment === 'center') {
      // Visual Anchor: Bottom-Center of Box
      // Logic: drawText X is the start of text.
      // Center X = field.x + width/2
      // Draw X = Center X - textWidth/2
      drawX = field.x + (field.width / 2) - (textWidth / 2);
    } else if (field.alignment === 'right') {
      // Visual Anchor: Bottom-Right of Box
      // Right X = field.x + width
      // Draw X = Right X - textWidth
      drawX = field.x + field.width - textWidth;
    } else {
      // Visual Anchor: Bottom-Left of Box
      // Left X = field.x
      // Draw X = Left X (No padding to match exact ruler measurement)
      drawX = field.x; 
    }

    page.drawText(field.value, {
      x: drawX,
      y: pdfY, 
      size: fontSize,
      font: helveticaFont,
      color: rgb(0, 0, 0),
    });
  }

  // 5. Serialize
  const pdfBytes = await pdfDoc.save();
  return pdfBytes;
};

export const downloadBlob = (data: Uint8Array, filename: string) => {
  const blob = new Blob([data], { type: 'application/pdf' });
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  window.URL.revokeObjectURL(url);
};

